from griffe.extensions import Extension
from griffe.docstrings import Docstring
import griffe

class CheckedExtension(Extension):
    def on_members_collected(self, node):
        """Append [checked] to function docstrings"""
        for member in node.members.values():
            if member.is_function:
                if member.docstring:
                    text = member.docstring.value + " [checked]"
                else:
                    text = "[checked]"
                member.docstring = Docstring(text, lineno=0, endlineno=0)

extension = CheckedExtension()
module = griffe.load("mypkg", extensions=[extension])

for name, member in module.members.items():
    if member.is_function:
        print(f"{name}: {member.docstring.value if member.docstring else 'No docstring'}")
